  mu_dda = mu_dda*tfunc
  CALL PUSHREAL8(v_ddan)
  v_ddan = v_ddan*tfunc
  CALL PUSHREAL8(v_ddap)
  v_ddap = v_ddap*tfunc
  CALL PUSHREAL8(mu_un)
  mu_un = mu_un*tfunc
  CALL PUSHREAL8(v_unn)
  v_unn = v_unn*tfunc
  CALL PUSHREAL8(v_unp)
  v_unp = v_unp*tfunc
  CALL PUSHREAL8(mu_ba)
  mu_ba = mu_ba*tfunc
  CALL PUSHREAL8(mu_prt)
  mu_prt = mu_prt*tfunc
  CALL PUSHREAL8(r_baresp_1)
  r_baresp_1 = r_baresp_1*tfunc
  CALL PUSHREAL8(r_prtresp_1)
  r_prtresp_1 = r_prtresp_1*tfunc
  CALL PUSHREAL8(mu_mz)
  mu_mz = mu_mz*tfunc
  CALL PUSHREAL8(r_mzresp_1)
  r_mzresp_1 = r_mzresp_1*tfunc
! 15N 源池比值
  rsp = y(isp15n)/(y(ispn)-y(isp15n)+eps)
  rtr = y(itr15n)/(y(itrn)-y(itr15n)+eps)
  rdda = y(idda15n)/(y(iddan)-y(idda15n)+eps)
  run = y(iun15n)/(y(iunn)-y(iun15n)+eps)
  rba = y(iba15n)/(y(iban)-y(iba15n)+eps)
  rprt = y(iprt15n)/(y(iprtn)-y(iprt15n)+eps)
  rmz = y(imz15n)/(y(imzn)-y(imz15n)+eps)
  rdet = y(idet15n)/(y(idetn)-y(idet15n)+eps)
  rldom = y(ildom15n)/(y(ildomn)-y(ildom15n)+eps)
  rnh4 = y(i15nh4)/(y(inh4)-y(i15nh4)+eps)
  rno3 = y(i15no3)/(y(ino3)-y(i15no3)+eps)
  dt = 3600.0d0
  no3_limit = 0.01d0
  nh4_limit = 0.001d0
!-----------------------------------------------------------------------
!      Microphytoplankton Processes
!-----------------------------------------------------------------------
! Nutrient quota Limitation
  nfunc_sp_n = (y(ispn)/y(ispc)-q_sp_min_n)/(q_sp_rdf_n-q_sp_min_n)
  nfunc_sp_p = (y(ispp)/y(ispc)-q_sp_min_p)/(q_sp_rdf_p-q_sp_min_p)
  IF (nfunc_sp_n .GT. nfunc_sp_p) THEN
    temp = nfunc_sp_p
    CALL PUSHCONTROL1B(0)
  ELSE
    temp = nfunc_sp_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .GT. c1) THEN
    temp = c1
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  IF (temp .LT. c0) THEN
    temp = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  pc_spmax = mu_sp*temp
! Light Limitation
  IF (pc_spmax .GT. c0 .AND. y(ispc) .GT. c0) THEN
    growspc = y(ispc)*pc_spmax*(c1-EXP(-(alpha_sp*y(ispchl)/y(ispc)*rlt/&
&     pc_spmax)))*EXP(-(a_sp*rlt))
    CALL PUSHCONTROL1B(1)
  ELSE
    growspc = c0
    CALL PUSHCONTROL1B(0)
  END IF
  IF (c0 .LT. (q_sp_max_n-y(ispn)/y(ispc))/(q_sp_max_n-q_sp_rdf_n)) THEN
    v_spmax_n = (q_sp_max_n-y(ispn)/y(ispc))/(q_sp_max_n-q_sp_rdf_n)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_spmax_n = c0
  END IF
  IF (c1 .GT. v_spmax_n) THEN
    CALL PUSHCONTROL1B(0)
    v_spmax_n = v_spmax_n
  ELSE
    v_spmax_n = c1
    CALL PUSHCONTROL1B(1)
  END IF
  growspnh4 = y(ispc)*v_spn*v_spmax_n*y(inh4)/(y(inh4)+k_nh4sp+y(ino3)*&
&   k_nh4sp/k_no3sp)
  growspno3 = y(ispc)*v_spn*v_spmax_n*y(ino3)/(y(ino3)+k_no3sp+y(inh4)*&
&   k_no3sp/k_nh4sp)
  growspn = growspnh4 + growspno3
! 添加15N同位素分馏效应
!--------------------------------------------------------------------
! SP NH4 assimilation
!--------------------------------------------------------------------
  u_nh4_sp = growspnh4*dt/(y(inh4)+eps)
  IF (0.9d0 .GT. u_nh4_sp) THEN
    y1 = u_nh4_sp
    CALL PUSHCONTROL1B(0)
  ELSE
    y1 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y1) THEN
    u_nh4_sp = y1
    CALL PUSHCONTROL1B(0)
  ELSE
    u_nh4_sp = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(inh4) .LT. nh4_limit) THEN
!情况B：底物浓度极低，饥饿状态，完全无分馏
    factor_nh4_sp = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_nh4_sp .LT. 1.0d-8) THEN
!情况A：底物充足但利用率极低，执行最大强度分馏（了解析极限）
    factor_nh4_sp = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
! 正常 Rayleigh 过程
    factor_nh4_sp = -((1.0d0-u_nh4_sp)/u_nh4_sp*LOG(1.0d0-u_nh4_sp))
    CALL PUSHCONTROL2B(0)
  END IF
! 计算 SP 同化NH4的特定 beta 值 
  beta_nh4_sp = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_sp)
! 最终 SP 的 15N 吸收方程
!--------------------------------------------------------------------
! SP NO3 assimilation
!--------------------------------------------------------------------
  u_no3_sp = growspno3*dt/(y(ino3)+eps)
  IF (0.9d0 .GT. u_no3_sp) THEN
    y2 = u_no3_sp
    CALL PUSHCONTROL1B(0)
  ELSE
    y2 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y2) THEN
    u_no3_sp = y2
    CALL PUSHCONTROL1B(0)
  ELSE
    u_no3_sp = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(ino3) .LT. no3_limit) THEN
!情况B
    factor_no3_sp = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_no3_sp .LT. 1.0d-8) THEN
!情况A
    factor_no3_sp = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_no3_sp = -((1.0d0-u_no3_sp)/u_no3_sp*LOG(1.0d0-u_no3_sp))
    CALL PUSHCONTROL2B(0)
  END IF
!计算 SP 同化NO3的特定 beta 值 
  beta_no3_sp = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_sp)
! 最终 SP 的 15N 吸收方程
! 浮游植物同化DIN的总15N
  IF (c0 .LT. (q_sp_max_p-y(ispp)/y(ispc))/(q_sp_max_p-q_sp_rdf_p)) THEN
    v_spmax_p = (q_sp_max_p-y(ispp)/y(ispc))/(q_sp_max_p-q_sp_rdf_p)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_spmax_p = c0
  END IF
  IF (c1 .GT. v_spmax_p) THEN
    CALL PUSHCONTROL1B(0)
    v_spmax_p = v_spmax_p
  ELSE
    v_spmax_p = c1
    CALL PUSHCONTROL1B(1)
  END IF
! Chlorophyll
  IF (rlt .GT. c0) THEN
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
  END IF
! SP excretion (could be also considered as mortality)
! Passive
  excrsp_1n = r_excrsp_1*y(ispn)
! 15N 排泄 1
  IF (c1 - y(ispn)/y(ispc)/q_sp_rdf_n .LT. c1 - y(ispp)/y(ispc)/&
&     q_sp_rdf_p) THEN
    CALL PUSHREAL8(temp)
    temp = c1 - y(ispp)/y(ispc)/q_sp_rdf_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = c1 - y(ispn)/y(ispc)/q_sp_rdf_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .LT. c0) THEN
    max1 = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    max1 = temp
    CALL PUSHCONTROL1B(1)
  END IF
  excrsp_2c = 0.5*y(ispc)*max1
  IF (excrsp_2c .GT. c0) THEN
    IF (c0 .LT. c1 - y(ispp)/y(ispn)/(q_sp_rdf_p/q_sp_rdf_n)) THEN
      temp = c1 - y(ispp)/y(ispn)/(q_sp_rdf_p/q_sp_rdf_n)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
      temp = c0
    END IF
    IF (c0 .LT. c1 - y(ispn)/y(ispp)/(q_sp_rdf_n/q_sp_rdf_p)) THEN
      temp1 = c1 - y(ispn)/y(ispp)/(q_sp_rdf_n/q_sp_rdf_p)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
      temp1 = c0
    END IF
    IF (0.25d0*y(ispn)*temp .GT. excrsp_2c*q_sp_rdf_n) THEN
      min1 = excrsp_2c*q_sp_rdf_n
      CALL PUSHCONTROL1B(0)
    ELSE
      min1 = 0.25d0*y(ispn)*temp
      CALL PUSHCONTROL1B(1)
    END IF
    excrsp_2n = 0.5*min1
    IF (0.25d0*y(ispp)*temp1 .GT. excrsp_2c*q_sp_rdf_p) THEN
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
    END IF
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
    excrsp_2n = c0
  END IF
! 15N 排泄 2
! Aggregation of SP
  pomspc = r_pomsp*y(ispc)*y(ispc)
  pomspn = pomspc*y(ispn)/y(ispc)
! 15N 碎屑产生
! SP grazed
  grazspc = mu_prt*y(iprtc)*y(ispc)*y(ispc)/(y(ispc)*y(ispc)+g_sp*g_sp+y&
&   (iunc)*y(iunc)/g_un/g_un*g_sp*g_sp+y(ibac)*y(ibac)/g_ba/g_ba*g_sp*&
&   g_sp)
  grazspn = grazspc*y(ispn)/y(ispc)
!--------------------------------------------------------------------
! SP be grazed 
!--------------------------------------------------------------------
  u_sp_graz = grazspn*dt/(y(ispn)+eps)
  IF (0.9d0 .GT. u_sp_graz) THEN
    y3 = u_sp_graz
    CALL PUSHCONTROL1B(0)
  ELSE
    y3 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y3) THEN
    u_sp_graz = y3
    CALL PUSHCONTROL1B(0)
  ELSE
    u_sp_graz = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_sp_graz .LT. 1.0d-8) THEN
    factor_sp_graz = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_sp_graz = -((1.0d0-u_sp_graz)/u_sp_graz*LOG(1.0d0-u_sp_graz))
    CALL PUSHCONTROL1B(0)
  END IF
!  计算SP被捕食的特定 beta 值 
  beta_sp_graz = rsp*(1.0d0-epsilon_g/1000.0d0*factor_sp_graz)
! SP被捕食15N吸收方程
  grazsp15n = grazspn*(beta_sp_graz/(1.0d0+beta_sp_graz))
  grazspp = grazspc*y(ispp)/y(ispc)
! SP derivs
!-----------------------------------------------------------------------
!      Trichodesmium Processes
!-----------------------------------------------------------------------
! Primary Production
! Nutrient quota Limitation
  nfunc_tr_n = (y(itrn)/y(itrc)-q_tr_min_n)/(q_tr_rdf_n-q_tr_min_n)
  nfunc_tr_p = (y(itrp)/y(itrc)-q_tr_min_p)/(q_tr_rdf_p-q_tr_min_p)
  IF (nfunc_tr_n .GT. nfunc_tr_p) THEN
    CALL PUSHREAL8(temp)
    temp = nfunc_tr_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = nfunc_tr_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .GT. c1) THEN
    temp = c1
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  IF (temp .LT. c0) THEN
    temp = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  pc_trmax = mu_tr*temp
! Light Limitation
  IF (pc_trmax .GT. c0 .AND. y(itrc) .GT. c0) THEN
    growtrc = y(itrc)*pc_trmax*(c1-EXP(-(alpha_tr*y(itrchl)/y(itrc)*rlt/&
&     pc_trmax)))*EXP(-(a_tr*rlt))
    CALL PUSHCONTROL1B(1)
  ELSE
    growtrc = c0
    CALL PUSHCONTROL1B(0)
  END IF
  IF (c0 .LT. (q_tr_max_n-y(itrn)/y(itrc))/(q_tr_max_n-q_tr_rdf_n)) THEN
    v_trmax_n = (q_tr_max_n-y(itrn)/y(itrc))/(q_tr_max_n-q_tr_rdf_n)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_trmax_n = c0
  END IF
  IF (c1 .GT. v_trmax_n) THEN
    CALL PUSHCONTROL1B(0)
    v_trmax_n = v_trmax_n
  ELSE
    v_trmax_n = c1
    CALL PUSHCONTROL1B(1)
  END IF
  growtrnh4 = y(itrc)*v_trn*v_trmax_n*y(inh4)/(y(inh4)+k_nh4tr+y(ino3)*&
&   k_nh4tr/k_no3tr)
  growtrno3 = y(itrc)*v_trn*v_trmax_n*y(ino3)/(y(ino3)+k_no3tr+y(inh4)*&
&   k_no3tr/k_nh4tr)
  IF (tdat(iz, istep) .LT. 20.0) THEN
    CALL PUSHCONTROL2B(0)
    maxtrnf = c0
  ELSE
    y4 = ((y(itrc)+growtrc-growtrno3*zeta)*q_tr_max_n-y(itrn)-growtrno3-&
&     growtrnh4)/(c1+zeta_nf*q_tr_max_n)*v_trmax_n*tfunc
    IF (c0 .LT. y4) THEN
      maxtrnf = y4
      CALL PUSHCONTROL2B(2)
    ELSE
      maxtrnf = c0
      CALL PUSHCONTROL2B(1)
    END IF
  END IF
  IF (y(itrc)*v_trn*v_trmax_n .GT. growtrnh4 + growtrno3 + maxtrnf) THEN
    growtrn = growtrnh4 + growtrno3 + maxtrnf
    CALL PUSHCONTROL1B(0)
  ELSE
    growtrn = y(itrc)*v_trn*v_trmax_n
    CALL PUSHCONTROL1B(1)
  END IF
  growtrnf = growtrn - growtrnh4 - growtrno3
! 15N 吸收与固氮 
!--------------------------------------------------------------------
! TR N2 fixation 
! --------------------------------------------------------------------
!--------------------------------------------------------------------
! TR NH4 Assimilation 
!--------------------------------------------------------------------
  u_nh4_tr = growtrnh4*dt/(y(inh4)+eps)
  IF (0.9d0 .GT. u_nh4_tr) THEN
    y5 = u_nh4_tr
    CALL PUSHCONTROL1B(0)
  ELSE
    y5 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y5) THEN
    u_nh4_tr = y5
    CALL PUSHCONTROL1B(0)
  ELSE
    u_nh4_tr = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(inh4) .LT. nh4_limit) THEN
! 情况B
    factor_nh4_tr = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_nh4_tr .LT. 1.0d-8) THEN
! 情况A
    factor_nh4_tr = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_nh4_tr = -((1.0d0-u_nh4_tr)/u_nh4_tr*LOG(1.0d0-u_nh4_tr))
    CALL PUSHCONTROL2B(0)
  END IF
!计算 TR 同化NH4的特定 beta 值 
  beta_nh4_tr = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_tr)
!--------------------------------------------------------------------
! TR NO3 Assimilation 
!--------------------------------------------------------------------
  u_no3_tr = growtrno3*dt/(y(ino3)+eps)
  IF (0.9d0 .GT. u_no3_tr) THEN
    y6 = u_no3_tr
    CALL PUSHCONTROL1B(0)
  ELSE
    y6 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y6) THEN
    u_no3_tr = y6
    CALL PUSHCONTROL1B(0)
  ELSE
    u_no3_tr = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(ino3) .LT. no3_limit) THEN
! 情况B
    factor_no3_tr = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_no3_tr .LT. 1.0d-8) THEN
! 情况A
    factor_no3_tr = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_no3_tr = -((1.0d0-u_no3_tr)/u_no3_tr*LOG(1.0d0-u_no3_tr))
    CALL PUSHCONTROL2B(0)
  END IF
!计算 TR 同化NO3的特定 beta 值 
  beta_no3_tr = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_tr)
! 最终 TR 的 15N 吸收方程
  IF (c0 .LT. (q_tr_max_p-y(itrp)/y(itrc))/(q_tr_max_p-q_tr_rdf_p)) THEN
    v_trmax_p = (q_tr_max_p-y(itrp)/y(itrc))/(q_tr_max_p-q_tr_rdf_p)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_trmax_p = c0
  END IF
  IF (c1 .GT. v_trmax_p) THEN
    CALL PUSHCONTROL1B(0)
    v_trmax_p = v_trmax_p
  ELSE
    v_trmax_p = c1
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(itrc)*(q_tr_max_p+q_tr_rdf_p)/2 - y(itrp) .LT. c0) THEN
    CALL PUSHCONTROL1B(0)
    max2 = c0
  ELSE
    max2 = y(itrc)*(q_tr_max_p+q_tr_rdf_p)/2 - y(itrp)
    CALL PUSHCONTROL1B(1)
  END IF
! Respiration
! Chlorophyll
  IF (rlt .GT. c0) THEN
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
  END IF
! TR excretion (mortality)
! Passive
  IF (c1 .GT. nfunc_tr_n) THEN
    min3 = nfunc_tr_n
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    min3 = c1
  END IF
  excrtr_1n = r_excrtr_1*y(itrn) + 0.5*r_excrtr_n*growtrnf*min3
  IF (c1 .GT. nfunc_tr_n) THEN
    min4 = nfunc_tr_n
    CALL PUSHCONTROL1B(0)
  ELSE
    min4 = c1
    CALL PUSHCONTROL1B(1)
  END IF
  excrtr_nh4 = 0.5*r_excrtr_n*growtrnf*min4
!--------------------------------------------------------------------
! TR NH4 excretion
!--------------------------------------------------------------------
  u_tr_excr = excrtr_nh4*dt/(y(itrn)+eps)
  IF (0.9d0 .GT. u_tr_excr) THEN
    y7 = u_tr_excr
    CALL PUSHCONTROL1B(0)
  ELSE
    y7 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y7) THEN
    u_tr_excr = y7
    CALL PUSHCONTROL1B(0)
  ELSE
    u_tr_excr = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_tr_excr .LT. 1.0d-8) THEN
    factor_tr_excr = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_tr_excr = -((1.0d0-u_tr_excr)/u_tr_excr*LOG(1.0d0-u_tr_excr))
    CALL PUSHCONTROL1B(0)
  END IF
  beta_tr_excr = rtr*(1.0d0-epsilon_exnh4/1000.0d0*factor_tr_excr)
  IF (c1 - y(itrn)/y(itrc)/q_tr_rdf_n .LT. c1 - y(itrp)/y(itrc)/&
&     q_tr_rdf_p) THEN
    CALL PUSHREAL8(temp)
    temp = c1 - y(itrp)/y(itrc)/q_tr_rdf_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = c1 - y(itrn)/y(itrc)/q_tr_rdf_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .LT. c0) THEN
    max3 = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    max3 = temp
    CALL PUSHCONTROL1B(1)
  END IF
  excrtr_2c = r_excrtr_2*y(itrc)*max3
  IF (excrtr_2c .GT. c0) THEN
    IF (c0 .LT. c1 - y(itrp)/y(itrn)/(q_tr_rdf_p/q_tr_rdf_n)) THEN
      temp = c1 - y(itrp)/y(itrn)/(q_tr_rdf_p/q_tr_rdf_n)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
      temp = c0
    END IF
    IF (c0 .LT. c1 - y(itrn)/y(itrp)/(q_tr_rdf_n/q_tr_rdf_p)) THEN
      CALL PUSHREAL8(temp1)
      temp1 = c1 - y(itrn)/y(itrp)/(q_tr_rdf_n/q_tr_rdf_p)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHREAL8(temp1)
      temp1 = c0
      CALL PUSHCONTROL1B(1)
    END IF
    IF (0.25d0*y(itrn)*temp .GT. excrtr_2c*q_tr_rdf_n) THEN
      min5 = excrtr_2c*q_tr_rdf_n
      CALL PUSHCONTROL1B(0)
    ELSE
      min5 = 0.25d0*y(itrn)*temp
      CALL PUSHCONTROL1B(1)
    END IF
    excrtr_2n = r_excrtr_2*min5
    IF (0.25d0*y(itrp)*temp1 .GT. excrtr_2c*q_tr_rdf_p) THEN
      min6 = excrtr_2c*q_tr_rdf_p
      CALL PUSHCONTROL1B(0)
    ELSE
      min6 = 0.25d0*y(itrp)*temp1
      CALL PUSHCONTROL1B(1)
    END IF
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
    excrtr_2n = c0
  END IF
! Aggregation of TR
  pomtrc = r_pomtr*y(itrc)*y(itrc)
  pomtrn = pomtrc*y(itrn)/y(itrc)
! TR grazed
  graztrc = mu_mz*y(imzc)*y(itrc)*y(itrc)/(y(itrc)*y(itrc)+g_tr*g_tr+y(&
&   iprtc)*y(iprtc)/g_prt/g_prt*g_tr*g_tr)
  graztrn = graztrc*y(itrn)/y(itrc)
!--------------------------------------------------------------------
! TR be grazed 
!--------------------------------------------------------------------
  u_tr_graz = graztrn*dt/(y(itrn)+eps)
  IF (0.9d0 .GT. u_tr_graz) THEN
    y8 = u_tr_graz
    CALL PUSHCONTROL1B(0)
  ELSE
    y8 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y8) THEN
    u_tr_graz = y8
    CALL PUSHCONTROL1B(0)
  ELSE
    u_tr_graz = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_tr_graz .LT. 1.0d-8) THEN
    factor_tr_graz = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_tr_graz = -((1.0d0-u_tr_graz)/u_tr_graz*LOG(1.0d0-u_tr_graz))
    CALL PUSHCONTROL1B(0)
  END IF
!  计算TR被捕食的特定 beta 值 
  beta_tr_graz = rtr*(1.0d0-epsilon_g/1000.0d0*factor_tr_graz)
!  TR被捕食15N吸收方程
  graztr15n = graztrn*(beta_tr_graz/(1.0d0+beta_tr_graz))
  graztrp = graztrc*y(itrp)/y(itrc)
! New TR
!-----------------------------------------------------------------------
!      Diatom-Associations Processes
!-----------------------------------------------------------------------
! Primary Production
! Nutrient quota Limitation
  nfunc_dda_n = (y(iddan)/y(iddac)-q_dda_min_n)/(q_dda_rdf_n-q_dda_min_n&
&   )
  nfunc_dda_p = (y(iddap)/y(iddac)-q_dda_min_p)/(q_dda_rdf_p-q_dda_min_p&
&   )
  IF (nfunc_dda_n .GT. nfunc_dda_p) THEN
    CALL PUSHREAL8(temp)
    temp = nfunc_dda_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = nfunc_dda_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .GT. c1) THEN
    temp = c1
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  IF (temp .LT. c0) THEN
    temp = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  pc_ddamax = mu_dda*temp
! Light Limitation
  IF (pc_ddamax .GT. c0 .AND. y(iddac) .GT. c0) THEN
    growddac = y(iddac)*pc_ddamax*(c1-EXP(-(alpha_dda*y(iddachl)/y(iddac&
&     )*rlt/pc_ddamax)))*EXP(-(a_dda*rlt))
    CALL PUSHCONTROL1B(1)
  ELSE
    growddac = c0
    CALL PUSHCONTROL1B(0)
  END IF
  IF (c0 .LT. (q_dda_max_n-y(iddan)/y(iddac))/(q_dda_max_n-q_dda_rdf_n)&
& ) THEN
    v_ddamax_n = (q_dda_max_n-y(iddan)/y(iddac))/(q_dda_max_n-&
&     q_dda_rdf_n)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_ddamax_n = c0
  END IF
  IF (c1 .GT. v_ddamax_n) THEN
    CALL PUSHCONTROL1B(0)
    v_ddamax_n = v_ddamax_n
  ELSE
    v_ddamax_n = c1
    CALL PUSHCONTROL1B(1)
  END IF
  growddanh4 = y(iddac)*v_ddan*v_ddamax_n*y(inh4)/(y(inh4)+k_nh4dda+y(&
&   ino3)*k_nh4dda/k_no3dda)
  growddano3 = y(iddac)*v_ddan*v_ddamax_n*y(ino3)/(y(ino3)+k_no3dda+y(&
&   inh4)*k_no3dda/k_nh4dda)
  IF (tdat(iz, istep) .LT. 20.0) THEN
    CALL PUSHCONTROL2B(0)
    maxddanf = c0
  ELSE
    y9 = ((y(iddac)+growddac-growddano3*zeta)*q_dda_max_n-y(iddan)-&
&     growddano3-growddanh4)/(c1+zeta_nf_dda*q_dda_max_n)*v_ddamax_n*&
&     tfunc
    IF (c0 .LT. y9) THEN
      maxddanf = y9
      CALL PUSHCONTROL2B(2)
    ELSE
      maxddanf = c0
      CALL PUSHCONTROL2B(1)
    END IF
  END IF
  IF (y(iddac)*v_ddan*v_ddamax_n .GT. growddanh4 + growddano3 + maxddanf&
& ) THEN
    growddan = growddanh4 + growddano3 + maxddanf
    CALL PUSHCONTROL1B(0)
  ELSE
    growddan = y(iddac)*v_ddan*v_ddamax_n
    CALL PUSHCONTROL1B(1)
  END IF
  growddanf = growddan - growddanh4 - growddano3
! 15N 吸收与固氮
!--------------------------------------------------------------------
! DDA N2 fixation 
!--------------------------------------------------------------------
!--------------------------------------------------------------------
! DDA NH4 Assimilation 
!--------------------------------------------------------------------
  u_nh4_dda = growddanh4*dt/(y(inh4)+eps)
  IF (0.9d0 .GT. u_nh4_dda) THEN
    y10 = u_nh4_dda
    CALL PUSHCONTROL1B(0)
  ELSE
    y10 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y10) THEN
    u_nh4_dda = y10
    CALL PUSHCONTROL1B(0)
  ELSE
    u_nh4_dda = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(inh4) .LT. nh4_limit) THEN
! 情况B
    factor_nh4_dda = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_nh4_dda .LT. 1.0d-8) THEN
! 情况A
    factor_nh4_dda = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_nh4_dda = -((1.0d0-u_nh4_dda)/u_nh4_dda*LOG(1.0d0-u_nh4_dda))
    CALL PUSHCONTROL2B(0)
  END IF
!计算 TR 同化NH4的特定 beta 值 
  beta_nh4_dda = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_dda)
!--------------------------------------------------------------------
! DDA NO3 Assimilation 
!--------------------------------------------------------------------
  u_no3_dda = growddano3*dt/(y(ino3)+eps)
  IF (0.9d0 .GT. u_no3_dda) THEN
    y11 = u_no3_dda
    CALL PUSHCONTROL1B(0)
  ELSE
    y11 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y11) THEN
    u_no3_dda = y11
    CALL PUSHCONTROL1B(0)
  ELSE
    u_no3_dda = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(ino3) .LT. no3_limit) THEN
! 情况B
    factor_no3_dda = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_no3_dda .LT. 1.0d-8) THEN
! 情况A
    factor_no3_dda = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_no3_dda = -((1.0d0-u_no3_dda)/u_no3_dda*LOG(1.0d0-u_no3_dda))
    CALL PUSHCONTROL2B(0)
  END IF
!计算 DDA 同化NO3的特定 beta 值 
  beta_no3_dda = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_dda)
! 最终 DDA 的 15N 吸收方程
  IF (c0 .LT. (q_dda_max_p-y(iddap)/y(iddac))/(q_dda_max_p-q_dda_rdf_p)&
& ) THEN
    v_ddamax_p = (q_dda_max_p-y(iddap)/y(iddac))/(q_dda_max_p-&
&     q_dda_rdf_p)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_ddamax_p = c0
  END IF
  IF (c1 .GT. v_ddamax_p) THEN
    CALL PUSHCONTROL1B(0)
    v_ddamax_p = v_ddamax_p
  ELSE
    v_ddamax_p = c1
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(iddac)*(q_dda_max_p+q_dda_rdf_p)/2 - y(iddap) .LT. c0) THEN
    CALL PUSHCONTROL1B(0)
    max4 = c0
  ELSE
    max4 = y(iddac)*(q_dda_max_p+q_dda_rdf_p)/2 - y(iddap)
    CALL PUSHCONTROL1B(1)
  END IF
! Respiration
! Chlorophyll
  IF (rlt .GT. c0) THEN
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
  END IF
! DDA excretion (mortality)
! Passive
  IF (c1 .GT. nfunc_dda_n) THEN
    min7 = nfunc_dda_n
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    min7 = c1
  END IF
  excrdda_1n = r_excrdda_1*y(iddan) + 0.5*r_excrdda_n*growddanf*min7
  IF (c1 .GT. nfunc_dda_n) THEN
    min8 = nfunc_dda_n
    CALL PUSHCONTROL1B(0)
  ELSE
    min8 = c1
    CALL PUSHCONTROL1B(1)
  END IF
  excrdda_nh4 = 0.5*r_excrdda_n*growddanf*min8
!-------------------------------------------------------------------
! DDA NH4 excretion
!--------------------------------------------------------------------
  u_dda_excr = excrdda_nh4*dt/(y(iddan)+eps)
  IF (0.9d0 .GT. u_dda_excr) THEN
    y12 = u_dda_excr
    CALL PUSHCONTROL1B(0)
  ELSE
    y12 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y12) THEN
    u_dda_excr = y12
    CALL PUSHCONTROL1B(0)
  ELSE
    u_dda_excr = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_dda_excr .LT. 1.0d-8) THEN
    factor_dda_excr = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_dda_excr = -((1.0d0-u_dda_excr)/u_dda_excr*LOG(1.0d0-&
&     u_dda_excr))
    CALL PUSHCONTROL1B(0)
  END IF
  beta_dda_excr = rdda*(1.0d0-epsilon_exnh4/1000.0d0*factor_dda_excr)
  IF (c1 - y(iddan)/y(iddac)/q_dda_rdf_n .LT. c1 - y(iddap)/y(iddac)/&
&     q_dda_rdf_p) THEN
    CALL PUSHREAL8(temp)
    temp = c1 - y(iddap)/y(iddac)/q_dda_rdf_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = c1 - y(iddan)/y(iddac)/q_dda_rdf_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .LT. c0) THEN
    max5 = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    max5 = temp
    CALL PUSHCONTROL1B(1)
  END IF
  excrdda_2c = r_excrdda_2*y(iddac)*max5
  IF (excrdda_2c .GT. c0) THEN
    IF (c0 .LT. c1 - y(iddap)/y(iddan)/(q_dda_rdf_p/q_dda_rdf_n)) THEN
      temp = c1 - y(iddap)/y(iddan)/(q_dda_rdf_p/q_dda_rdf_n)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
      temp = c0
    END IF
    IF (c0 .LT. c1 - y(iddan)/y(iddap)/(q_dda_rdf_n/q_dda_rdf_p)) THEN
      CALL PUSHREAL8(temp1)
      temp1 = c1 - y(iddan)/y(iddap)/(q_dda_rdf_n/q_dda_rdf_p)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHREAL8(temp1)
      temp1 = c0
      CALL PUSHCONTROL1B(1)
    END IF
    IF (0.25d0*y(iddan)*temp .GT. excrdda_2c*q_dda_rdf_n) THEN
      min9 = excrdda_2c*q_dda_rdf_n
      CALL PUSHCONTROL1B(0)
    ELSE
      min9 = 0.25d0*y(iddan)*temp
      CALL PUSHCONTROL1B(1)
    END IF
    excrdda_2n = r_excrdda_2*min9
    IF (0.25d0*y(iddap)*temp1 .GT. excrdda_2c*q_dda_rdf_p) THEN
      min10 = excrdda_2c*q_dda_rdf_p
      CALL PUSHCONTROL1B(0)
    ELSE
      min10 = 0.25d0*y(iddap)*temp1
      CALL PUSHCONTROL1B(1)
    END IF
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
    excrdda_2n = c0
  END IF
! Aggregation of DDA
  pomddac = r_pomdda*y(iddac)*y(iddac)
  pomddan = pomddac*y(iddan)/y(iddac)
! DDA grazed
  grazddac = mu_mz*y(imzc)*y(iddac)*y(iddac)/(y(iddac)*y(iddac)+g_dda*&
&   g_dda+y(iprtc)*y(iprtc)/g_prt/g_prt*g_dda*g_dda)
  grazddan = grazddac*y(iddan)/y(iddac)
!--------------------------------------------------------------------
! DDA be grazed 
!--------------------------------------------------------------------
  u_dda_graz = grazddan*dt/(y(iddan)+eps)
  IF (0.9d0 .GT. u_dda_graz) THEN
    y13 = u_dda_graz
    CALL PUSHCONTROL1B(0)
  ELSE
    y13 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y13) THEN
    u_dda_graz = y13
    CALL PUSHCONTROL1B(0)
  ELSE
    u_dda_graz = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_dda_graz .LT. 1.0d-8) THEN
    factor_dda_graz = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_dda_graz = -((1.0d0-u_dda_graz)/u_dda_graz*LOG(1.0d0-&
&     u_dda_graz))
    CALL PUSHCONTROL1B(0)
  END IF
! 计算DDA被捕食的特定 beta 值 
  beta_dda_graz = rdda*(1.0d0-epsilon_g/1000.0d0*factor_dda_graz)
! DDA被捕食15N吸收方程
  grazdda15n = grazddan*(beta_dda_graz/(1.0d0+beta_dda_graz))
  grazddap = grazddac*y(iddap)/y(iddac)
! New DDA
!-----------------------------------------------------------------------
! Unicellular N2-fixers Processes
!-----------------------------------------------------------------------
! Primary Production
! Nutrient quota Limitation
  nfunc_un_n = (y(iunn)/y(iunc)-q_un_min_n)/(q_un_rdf_n-q_un_min_n)
  nfunc_un_p = (y(iunp)/y(iunc)-q_un_min_p)/(q_un_rdf_p-q_un_min_p)
  IF (nfunc_un_n .GT. nfunc_un_p) THEN
    CALL PUSHREAL8(temp)
    temp = nfunc_un_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = nfunc_un_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .GT. c1) THEN
    temp = c1
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  IF (temp .LT. c0) THEN
    temp = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  pc_unmax = mu_un*temp
! Light Limitation
  IF (pc_unmax .GT. c0 .AND. y(iunc) .GT. c0) THEN
    growunc = y(iunc)*pc_unmax*(c1-EXP(-(alpha_un*y(iunchl)/y(iunc)*rlt/&
&     pc_unmax)))*EXP(-(a_un*rlt))
    CALL PUSHCONTROL1B(1)
  ELSE
    growunc = c0
    CALL PUSHCONTROL1B(0)
  END IF
  IF (c0 .LT. (q_un_max_n-y(iunn)/y(iunc))/(q_un_max_n-q_un_rdf_n)) THEN
    v_unmax_n = (q_un_max_n-y(iunn)/y(iunc))/(q_un_max_n-q_un_rdf_n)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_unmax_n = c0
  END IF
  IF (c1 .GT. v_unmax_n) THEN
    CALL PUSHCONTROL1B(0)
    v_unmax_n = v_unmax_n
  ELSE
    v_unmax_n = c1
    CALL PUSHCONTROL1B(1)
  END IF
  growunnh4 = y(iunc)*v_unn*v_unmax_n*y(inh4)/(y(inh4)+k_nh4un+y(ino3)*&
&   k_nh4un/k_no3un)
  growunno3 = y(iunc)*v_unn*v_unmax_n*y(ino3)/(y(ino3)+k_no3un+y(inh4)*&
&   k_no3un/k_nh4un)
  y14 = ((y(iunc)+growunc-growunno3*zeta)*q_un_max_n-y(iunn)-growunno3-&
&   growunnh4)/(c1+zeta_nf*q_un_max_n)*v_unmax_n*tfunc
  IF (c0 .LT. y14) THEN
    maxunnf = y14
    CALL PUSHCONTROL1B(0)
  ELSE
    maxunnf = c0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(iunc)*v_unn*v_unmax_n .GT. growunnh4 + growunno3 + maxunnf) THEN
    growunn = growunnh4 + growunno3 + maxunnf
    CALL PUSHCONTROL1B(0)
  ELSE
    growunn = y(iunc)*v_unn*v_unmax_n
    CALL PUSHCONTROL1B(1)
  END IF
  growunnf = growunn - growunnh4 - growunno3
! 15N 吸收与固氮
!--------------------------------------------------------------------
! UN N2 fixation 
!--------------------------------------------------------------------
  beta_nf = r_std*(1.0d0-epsilon_nf/1000.0d0)
!--------------------------------------------------------------------
! UN NH4 Assimilation 
!--------------------------------------------------------------------
  u_nh4_un = growunnh4*dt/(y(inh4)+eps)
  IF (0.9d0 .GT. u_nh4_un) THEN
    y15 = u_nh4_un
    CALL PUSHCONTROL1B(0)
  ELSE
    y15 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y15) THEN
    u_nh4_un = y15
    CALL PUSHCONTROL1B(0)
  ELSE
    u_nh4_un = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(inh4) .LT. nh4_limit) THEN
! 情况B
    factor_nh4_un = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_nh4_un .LT. 1.0d-8) THEN
! 情况A
    factor_nh4_un = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_nh4_un = -((1.0d0-u_nh4_un)/u_nh4_un*LOG(1.0d0-u_nh4_un))
    CALL PUSHCONTROL2B(0)
  END IF
!计算 UN 同化NH4的特定 beta 值 
  beta_nh4_un = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_un)
!--------------------------------------------------------------------
! UN NO3 Assimilation 
!--------------------------------------------------------------------
  u_no3_un = growunno3*dt/(y(ino3)+eps)
  IF (0.9d0 .GT. u_no3_un) THEN
    y16 = u_no3_un
    CALL PUSHCONTROL1B(0)
  ELSE
    y16 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y16) THEN
    u_no3_un = y16
    CALL PUSHCONTROL1B(0)
  ELSE
    u_no3_un = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(ino3) .LT. no3_limit) THEN
! 情况B
    factor_no3_un = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_no3_un .LT. 1.0d-8) THEN
! 情况A
    factor_no3_un = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_no3_un = -((1.0d0-u_no3_un)/u_no3_un*LOG(1.0d0-u_no3_un))
    CALL PUSHCONTROL2B(0)
  END IF
!计算 UN 同化NO3的特定 beta 值 
  beta_no3_un = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_un)
  IF (c0 .LT. (q_un_max_p-y(iunp)/y(iunc))/(q_un_max_p-q_un_rdf_p)) THEN
    v_unmax_p = (q_un_max_p-y(iunp)/y(iunc))/(q_un_max_p-q_un_rdf_p)
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    v_unmax_p = c0
  END IF
  IF (c1 .GT. v_unmax_p) THEN
    CALL PUSHCONTROL1B(0)
    v_unmax_p = v_unmax_p
  ELSE
    v_unmax_p = c1
    CALL PUSHCONTROL1B(1)
  END IF
! Chlorophyll
  IF (rlt .GT. c0) THEN
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
  END IF
! UN excretion
! Passive
  IF (c1 .GT. nfunc_un_n) THEN
    min11 = nfunc_un_n
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    min11 = c1
  END IF
  excrun_1n = r_excrun_1*y(iunn) + 0.5*r_excrun_n*growunnf*min11
  IF (c1 .GT. nfunc_un_n) THEN
    min12 = nfunc_un_n
    CALL PUSHCONTROL1B(0)
  ELSE
    min12 = c1
    CALL PUSHCONTROL1B(1)
  END IF
  excrun_nh4 = 0.5*r_excrun_n*growunnf*min12
!-------------------------------------------------------------------
! UN NH4 excretion
!--------------------------------------------------------------------
  u_un_excr = excrun_nh4*dt/(y(iunn)+eps)
  IF (0.9d0 .GT. u_un_excr) THEN
    y17 = u_un_excr
    CALL PUSHCONTROL1B(0)
  ELSE
    y17 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y17) THEN
    u_un_excr = y17
    CALL PUSHCONTROL1B(0)
  ELSE
    u_un_excr = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_un_excr .LT. 1.0d-8) THEN
    factor_un_excr = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_un_excr = -((1.0d0-u_un_excr)/u_un_excr*LOG(1.0d0-u_un_excr))
    CALL PUSHCONTROL1B(0)
  END IF
  beta_un_excr = run*(1.0d0-epsilon_exnh4/1000.0d0*factor_un_excr)
  IF (c1 - y(iunn)/y(iunc)/q_un_rdf_n .LT. c1 - y(iunp)/y(iunc)/&
&     q_un_rdf_p) THEN
    CALL PUSHREAL8(temp)
    temp = c1 - y(iunp)/y(iunc)/q_un_rdf_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = c1 - y(iunn)/y(iunc)/q_un_rdf_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .LT. c0) THEN
    max6 = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    max6 = temp
    CALL PUSHCONTROL1B(1)
  END IF
  excrun_2c = r_excrun_2*y(iunc)*max6
  IF (excrun_2c .GT. c0) THEN
    IF (c0 .LT. c1 - y(iunp)/y(iunn)/(q_un_rdf_p/q_un_rdf_n)) THEN
      temp = c1 - y(iunp)/y(iunn)/(q_un_rdf_p/q_un_rdf_n)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHCONTROL1B(1)
      temp = c0
    END IF
    IF (c0 .LT. c1 - y(iunn)/y(iunp)/(q_un_rdf_n/q_un_rdf_p)) THEN
      CALL PUSHREAL8(temp1)
      temp1 = c1 - y(iunn)/y(iunp)/(q_un_rdf_n/q_un_rdf_p)
      CALL PUSHCONTROL1B(0)
    ELSE
      CALL PUSHREAL8(temp1)
      temp1 = c0
      CALL PUSHCONTROL1B(1)
    END IF
    IF (0.25d0*y(iunn)*temp .GT. excrun_2c*q_un_rdf_n) THEN
      min13 = excrun_2c*q_un_rdf_n
      CALL PUSHCONTROL1B(0)
    ELSE
      min13 = 0.25d0*y(iunn)*temp
      CALL PUSHCONTROL1B(1)
    END IF
    excrun_2n = r_excrun_2*min13
    IF (0.25d0*y(iunp)*temp1 .GT. excrun_2c*q_un_rdf_p) THEN
      min14 = excrun_2c*q_un_rdf_p
      CALL PUSHCONTROL1B(0)
    ELSE
      min14 = 0.25d0*y(iunp)*temp1
      CALL PUSHCONTROL1B(1)
    END IF
    CALL PUSHCONTROL1B(1)
  ELSE
    CALL PUSHCONTROL1B(0)
    excrun_2n = c0
  END IF
! Aggregation of UN
  pomunc = r_pomun*y(iunc)*y(iunc)
  pomunn = pomunc*y(iunn)/y(iunc)
! UN grazed
  grazunc = mu_prt*y(iprtc)*y(iunc)*y(iunc)/(y(iunc)*y(iunc)+g_un*g_un+y&
&   (ispc)*y(ispc)/g_sp/g_sp*g_un*g_un+y(ibac)*y(ibac)/g_ba/g_ba*g_un*&
&   g_un)
  grazunn = grazunc*y(iunn)/y(iunc)
!--------------------------------------------------------------------
! UN be grazed 
!--------------------------------------------------------------------
  u_un_graz = grazunn*dt/(y(iunn)+eps)
  IF (0.9d0 .GT. u_un_graz) THEN
    y18 = u_un_graz
    CALL PUSHCONTROL1B(0)
  ELSE
    y18 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y18) THEN
    u_un_graz = y18
    CALL PUSHCONTROL1B(0)
  ELSE
    u_un_graz = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_un_graz .LT. 1.0d-8) THEN
    factor_un_graz = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_un_graz = -((1.0d0-u_un_graz)/u_un_graz*LOG(1.0d0-u_un_graz))
    CALL PUSHCONTROL1B(0)
  END IF
!计算UN被捕食的特定 beta 值 
  beta_un_graz = run*(1.0d0-epsilon_g/1000.0d0*factor_un_graz)
! UN被捕食15N吸收方程
  grazun15n = grazunn*(beta_un_graz/(1.0d0+beta_un_graz))
  grazunp = grazunc*y(iunp)/y(iunc)
! New UN
!-----------------------------------------------------------------------
!      Bacterial Processes
!-----------------------------------------------------------------------
! 1. Gross Grow
! Maximum possible C amount for bacterial use
  alc = y(ildomc)
!temp = MIN(c1, exp(b_SDONlabi * (y(iSDOMn)/y(iSDOMc)/q_BA_n - c1)) )
!temp = MIN(temp, exp(b_SDOPlabi * (y(iSDOMp)/y(iSDOMc)/q_BA_p - c1)) )
  asc = y(isdomc)*r_sdom
! Carbon Usage
  nfunc_ba_n = y(iban)/y(ibac)/q_ba_n
  nfunc_ba_p = y(ibap)/y(ibac)/q_ba_p
  IF (nfunc_ba_n .GT. nfunc_ba_p) THEN
    CALL PUSHREAL8(temp)
    temp = nfunc_ba_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = nfunc_ba_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .GT. c1) THEN
    temp = c1
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  growbaldoc = mu_ba*y(ibac)*temp*alc/(alc+k_dom+asc)
  growbasdoc = mu_ba*y(ibac)*temp*asc/(asc+k_dom+alc)
! DON and DOP usage
! available labile N
  growbaldon = growbaldoc/y(ildomc)*y(ildomn)
! available labile P
  growbaldop = growbaldoc/y(ildomc)*y(ildomp)
  y19 = y(isdomn)/y(isdomc) + f_baslct/nfunc_ba_n*(q_ba_n-y(isdomn)/y(&
&   isdomc))
  IF (q_ba_n .GT. y19) THEN
    min15 = y19
    CALL PUSHCONTROL1B(0)
  ELSE
    min15 = q_ba_n
    CALL PUSHCONTROL1B(1)
  END IF
  growbasdon = growbasdoc*min15
  y20 = y(isdomp)/y(isdomc) + f_baslct/nfunc_ba_p*(q_ba_p-y(isdomp)/y(&
&   isdomc))
  IF (q_ba_p .GT. y20) THEN
    min16 = y20
    CALL PUSHCONTROL1B(0)
  ELSE
    min16 = q_ba_p
    CALL PUSHCONTROL1B(1)
  END IF
! 15N DON 摄取
  IF (c1 .GT. 1/nfunc_ba_n) THEN
    min17 = 1/nfunc_ba_n
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    min17 = c1
  END IF
! inorganic nutrients uptake
  growbanh4 = growbaldon/y(ildomn)*y(inh4)*min17
  IF (nfunc_ba_n .LT. c1) THEN
    IF (c1 .GT. 1/nfunc_ba_n) THEN
      min19 = 1/nfunc_ba_n
      CALL PUSHCONTROL1B(0)
    ELSE
      min19 = c1
      CALL PUSHCONTROL1B(1)
    END IF
    x1 = 0.1*(growbaldon+growbasdon)/(y(ildomn)+y(isdomn))*y(ino3)*min19
    IF (x1 .GT. (growbaldon+growbasdon)/(y(ildomn)+y(isdomn))*(y(ino3)+y&
&       (inh4)) - growbanh4) THEN
      growbano3 = (growbaldon+growbasdon)/(y(ildomn)+y(isdomn))*(y(ino3)&
&       +y(inh4)) - growbanh4
      CALL PUSHCONTROL1B(0)
    ELSE
      growbano3 = x1
      CALL PUSHCONTROL1B(1)
    END IF
    IF (c0 .LT. growbano3) THEN
      CALL PUSHCONTROL2B(2)
      growbano3 = growbano3
    ELSE
      growbano3 = c0
      CALL PUSHCONTROL2B(1)
    END IF
  ELSE
    growbano3 = c0
    CALL PUSHCONTROL2B(0)
  END IF
  IF (c1 .GT. 1/nfunc_ba_p) THEN
    min18 = 1/nfunc_ba_p
    CALL PUSHCONTROL1B(0)
  ELSE
    min18 = c1
    CALL PUSHCONTROL1B(1)
  END IF
! 15N 无机摄取
!--------------------------------------------------------------------
! BA NH4 Assimilation 
!--------------------------------------------------------------------
  u_nh4_ba = growbanh4*dt/(y(inh4)+eps)
  IF (0.9d0 .GT. u_nh4_ba) THEN
    y21 = u_nh4_ba
    CALL PUSHCONTROL1B(0)
  ELSE
    y21 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y21) THEN
    u_nh4_ba = y21
    CALL PUSHCONTROL1B(0)
  ELSE
    u_nh4_ba = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(inh4) .LT. nh4_limit) THEN
! 情况B
    factor_nh4_ba = 0.0d0
    CALL PUSHCONTROL2B(2)
  ELSE IF (u_nh4_ba .LT. 1.0d-8) THEN
! 情况A
    factor_nh4_ba = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_nh4_ba = -((1.0d0-u_nh4_ba)/u_nh4_ba*LOG(1.0d0-u_nh4_ba))
    CALL PUSHCONTROL2B(0)
  END IF
!计算BA 同化NH4的特定 beta 值 
  beta_nh4_ba = rnh4*(1.0d0-epsilon_anh4/1000.0d0*factor_nh4_ba)
!--------------------------------------------------------------------
! BA NO3 Assimilation 
!--------------------------------------------------------------------
  u_no3_ba = growbano3*dt/(y(ino3)+eps)
  IF (0.9d0 .GT. u_no3_ba) THEN
    y22 = u_no3_ba
    CALL PUSHCONTROL1B(0)
  ELSE
    y22 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y22) THEN
    u_no3_ba = y22
    CALL PUSHCONTROL1B(0)
  ELSE
    u_no3_ba = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(ino3) .LT. no3_limit) THEN
! 情况B
    factor_no3_ba = 0.0d0
    CALL PUSHCONTROL2B(0)
  ELSE IF (u_no3_ba .LT. 1.0d-8) THEN
! 情况A
    factor_no3_ba = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_no3_ba = -((1.0d0-u_no3_ba)/u_no3_ba*LOG(1.0d0-u_no3_ba))
    CALL PUSHCONTROL2B(2)
  END IF
!计算 BA 同化NO3的特定 beta 值 
  beta_no3_ba = rno3*(1.0d0-epsilon_ano3/1000.0d0*factor_no3_ba)
! Bacteria gross growth
  growbac = growbaldoc + growbasdoc
! 2. respiration
! 3. excreting refractory DOM
  refrbac = r_barefr*y(ibac)
  refrban = q_refrdom_n*refrbac
! 4. excreting semi-labile DOM and regenerating DIN
  IF (y(ibac) .LT. y(iban)/q_ba_n .AND. y(ibac) .LT. y(ibap)/q_ba_p) &
& THEN
!Cabon in short
    excrban = c0
    remiban = r_baremi*(y(iban)-y(ibac)*q_ba_n)
    CALL PUSHCONTROL2B(2)
  ELSE IF (y(ibac) .GT. y(iban)/q_ba_n .AND. y(ibap)/q_ba_p .GT. y(iban)&
&     /q_ba_n) THEN
!Nitrogen in short
    excrban = c0
    remiban = c0
    CALL PUSHCONTROL2B(1)
  ELSE
!Phosphorus in short
    excrban = r_baadju*(y(iban)-y(ibap)/q_ba_p*q_ba_n)
    remiban = c0
    CALL PUSHCONTROL2B(0)
  END IF
! 计算BA再矿化的特定 beta 值 
  beta_ba_remi = rba*(1.0d0-epsilon_remin/1000.0d0)
! BA再矿化的15N吸收方程
!6. removal by grazing
  grazbac = mu_prt*y(iprtc)*y(ibac)*y(ibac)/(y(ibac)*y(ibac)+g_ba*g_ba+y&
&   (ispc)*y(ispc)/g_sp/g_sp*g_ba*g_ba+y(iunc)*y(iunc)/g_un/g_un*g_ba*&
&   g_ba)
  grazban = grazbac/y(ibac)*y(iban)
!--------------------------------------------------------------------
! BA be grazed 
!--------------------------------------------------------------------
  u_ba_graz = grazban*dt/(y(iban)+eps)
  IF (0.9d0 .GT. u_ba_graz) THEN
    y23 = u_ba_graz
    CALL PUSHCONTROL1B(0)
  ELSE
    y23 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y23) THEN
    u_ba_graz = y23
    CALL PUSHCONTROL1B(0)
  ELSE
    u_ba_graz = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_ba_graz .LT. 1.0d-8) THEN
    factor_ba_graz = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_ba_graz = -((1.0d0-u_ba_graz)/u_ba_graz*LOG(1.0d0-u_ba_graz))
    CALL PUSHCONTROL1B(0)
  END IF
!  计算BA被捕食的特定 beta 值 
  beta_ba_graz = rba*(1.0d0-epsilon_g/1000.0d0*factor_ba_graz)
! BA被捕食15N吸收方程
  grazba15n = grazban*(beta_ba_graz/(1.0d0+beta_ba_graz))
  grazbap = grazbac/y(ibac)*y(ibap)
!6b. Mortality due to viruses
  mortban = r_bamort*y(iban)
!7. BA Derivs
!8. Flux of inorganic nutrients through bacteria
!-----------------------------------------------------------------------
!      Protozoan Processes
!-----------------------------------------------------------------------
! 1. gross growth
  growprtc = grazspc + grazbac + grazunc
  growprtn = grazspn + grazban + grazunn
  growprt15n = grazsp15n + grazba15n + grazun15n
  growprtp = grazspp + grazbap + grazunp
! 2. DOM excretion
  excrprtsdomn = (c1-f_exprtldom)*r_prtex*growprtn*y(iprtn)/y(iprtc)/&
&   q_prt_n
! 3. respiration
  IF (c1 - y(iprtn)/y(iprtc)/q_prt_n .LT. c1 - y(iprtp)/y(iprtc)/q_prt_p&
& ) THEN
    CALL PUSHREAL8(temp)
    temp = c1 - y(iprtp)/y(iprtc)/q_prt_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = c1 - y(iprtn)/y(iprtc)/q_prt_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (c0 .LT. temp) THEN
    CALL PUSHCONTROL1B(0)
    temp = temp
  ELSE
    temp = c0
    CALL PUSHCONTROL1B(1)
  END IF
  excrprtsdom2c = r_prtadju*y(iprtc)*temp
  excrprtsdom2n = 0.5d0*excrprtsdom2c*y(iprtn)/y(iprtc)
  IF (r_prtremi*(y(iprtn)-q_prt_n*y(iprtc)) .LT. r_prtremi*(y(iprtn)-&
&     q_prt_n/q_prt_p*y(iprtp))) THEN
    remiprtn = r_prtremi*(y(iprtn)-q_prt_n/q_prt_p*y(iprtp))
    CALL PUSHCONTROL1B(0)
  ELSE
    remiprtn = r_prtremi*(y(iprtn)-q_prt_n*y(iprtc))
    CALL PUSHCONTROL1B(1)
  END IF
  IF (c0 .LT. remiprtn) THEN
    CALL PUSHCONTROL1B(0)
    remiprtn = remiprtn
  ELSE
    remiprtn = c0
    CALL PUSHCONTROL1B(1)
  END IF
!计算PRT再矿化的特定 beta 值 
  beta_prt_remi = rprt*(1.0d0-epsilon_remin/1000.0d0)
!PRT再矿化的15N吸收方程
  IF (r_prtremi*(y(iprtp)-q_prt_p*y(iprtc)) .LT. r_prtremi*(y(iprtp)-&
&     q_prt_p/q_prt_n*y(iprtn))) THEN
    remiprtp = r_prtremi*(y(iprtp)-q_prt_p/q_prt_n*y(iprtn))
    CALL PUSHCONTROL1B(0)
  ELSE
    remiprtp = r_prtremi*(y(iprtp)-q_prt_p*y(iprtc))
    CALL PUSHCONTROL1B(1)
  END IF
  IF (c0 .LT. remiprtp) THEN
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
  END IF
! POM production
  pomprtc = r_pomprt*growprtc
  pomprtn = pomprtc*q_pom_n
! 6. removal by microzooplankton
  grazprtc = mu_mz*y(imzc)*y(iprtc)*y(iprtc)/(y(iprtc)*y(iprtc)+g_prt*&
&   g_prt+y(itrc)*y(itrc)/g_tr/g_tr*g_prt*g_prt+y(iddac)*y(iddac)/g_dda/&
&   g_dda*g_prt*g_prt)
  grazprtn = grazprtc*y(iprtn)/y(iprtc)
!--------------------------------------------------------------------
! PRT be grazed 
!--------------------------------------------------------------------
  u_prt_graz = grazprtn*dt/(y(iprtn)+eps)
  IF (0.9d0 .GT. u_prt_graz) THEN
    y24 = u_prt_graz
    CALL PUSHCONTROL1B(0)
  ELSE
    y24 = 0.9d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y24) THEN
    u_prt_graz = y24
    CALL PUSHCONTROL1B(0)
  ELSE
    u_prt_graz = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (u_prt_graz .LT. 1.0d-8) THEN
    factor_prt_graz = 1.0d0
    CALL PUSHCONTROL1B(1)
  ELSE
    factor_prt_graz = -((1.0d0-u_prt_graz)/u_prt_graz*LOG(1.0d0-&
&     u_prt_graz))
    CALL PUSHCONTROL1B(0)
  END IF
!  计算PRT被捕食的特定 beta 值 
  beta_prt_graz = rprt*(1.0d0-epsilon_g/1000.0d0*factor_prt_graz)
! PRT被捕食15N吸收方程
  grazprt15n = grazprtn*(beta_prt_graz/(1.0d0+beta_prt_graz))
  grazprtp = grazprtc*y(iprtp)/y(iprtc)
! 7. new PRT
!-----------------------------------------------------------------------
!      Metozoan Processes
!-----------------------------------------------------------------------
! 1. gross growth
  growmzc = grazprtc + graztrc + grazddac
  growmzn = grazprtn + graztrn + grazddan
  growmz15n = grazprt15n + graztr15n + grazdda15n
  growmzp = grazprtp + graztrp + grazddap
! 2. DOM excretion
  excrmzsdomn = (c1-f_exmzldom)*r_mzex*growmzn*y(imzn)/y(imzc)/q_mz_n
! 3. respiration
  IF (c1 - y(imzn)/y(imzc)/q_mz_n .LT. c1 - y(imzp)/y(imzc)/q_mz_p) THEN
    CALL PUSHREAL8(temp)
    temp = c1 - y(imzp)/y(imzc)/q_mz_p
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHREAL8(temp)
    temp = c1 - y(imzn)/y(imzc)/q_mz_n
    CALL PUSHCONTROL1B(1)
  END IF
  IF (temp .LT. c0) THEN
    temp = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    temp = temp
  END IF
  excrmzsdom2c = r_mzadju*y(imzc)*temp
  excrmzsdom2n = excrmzsdom2c*y(imzn)/y(imzc)*0.5d0
  IF (r_mzremi*(y(imzn)-q_mz_n*y(imzc)) .LT. r_mzremi*(y(imzn)-q_mz_n/&
&     q_mz_p*y(imzp))) THEN
    remimzn = r_mzremi*(y(imzn)-q_mz_n/q_mz_p*y(imzp))
    CALL PUSHCONTROL1B(0)
  ELSE
    remimzn = r_mzremi*(y(imzn)-q_mz_n*y(imzc))
    CALL PUSHCONTROL1B(1)
  END IF
  IF (remimzn .LT. c0) THEN
    remimzn = c0
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
    remimzn = remimzn
  END IF
!  计算MZ再矿化的特定 beta 值 
  beta_mz_remi = rmz*(1.0d0-epsilon_remin/1000.0d0)
!  MZ再矿化的15N吸收方程
  IF (r_mzremi*(y(imzp)-q_mz_p*y(imzc)) .LT. r_mzremi*(y(imzp)-q_mz_p/&
&     q_mz_n*y(imzn))) THEN
    remimzp = r_mzremi*(y(imzp)-q_mz_p/q_mz_n*y(imzn))
    CALL PUSHCONTROL1B(0)
  ELSE
    remimzp = r_mzremi*(y(imzp)-q_mz_p*y(imzc))
    CALL PUSHCONTROL1B(1)
  END IF
  IF (remimzp .LT. c0) THEN
    CALL PUSHCONTROL1B(0)
  ELSE
    CALL PUSHCONTROL1B(1)
  END IF
! 6. indissolved POM and refractory DOM production
  pommzc = r_mzpom*growmzc
  pommzn = q_pom_n*pommzc
! 7. removal by higher-level zooplankton
  remvmzc = r_mzremv*y(imzc)*y(imzc)
  remvmzn = remvmzc/y(imzc)*y(imzn)
  remvmz15n = remvmzn*(rmz/(1.0d0+rmz))
  remvmzp = remvmzc/y(imzc)*y(imzp)
! 8. new MZ
!-----------------------------------------------------------------------
!      Detritus Processes
!-----------------------------------------------------------------------
  disdetn = remin*y(idetn)*remin_prf_n
!  计算DET再矿化的特定 beta 值 
  beta_det_remi = rdet*(1.0d0-epsilon_remin/1000.0d0)
! DET再矿化的15N吸收方程
!disDET15n    = disDETn * (rDET/(1+rDET))
!-----------------------------------------------------------------------
!   Inorganic Nutrients Processes
!-----------------------------------------------------------------------
  nitrf = r_nitrf*y(inh4)
!--------------------------------------------------------------------
! nitrification
!--------------------------------------------------------------------
!  计算硝化过程的beta 值 
  u_nitrf = nitrf*dt/(y(inh4)+eps)
  IF (0.90d0 .GT. u_nitrf) THEN
    y25 = u_nitrf
    CALL PUSHCONTROL1B(0)
  ELSE
    y25 = 0.90d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (0.0d0 .LT. y25) THEN
    u_nitrf = y25
    CALL PUSHCONTROL1B(0)
  ELSE
    u_nitrf = 0.0d0
    CALL PUSHCONTROL1B(1)
  END IF
  IF (y(inh4) .LT. nh4_limit) THEN
! 情况B
    factor_nitrf = 0.0d0
    CALL PUSHCONTROL2B(0)
  ELSE IF (u_nitrf .LT. 1.0d-8) THEN
! 情况A
    factor_nitrf = 1.0d0
    CALL PUSHCONTROL2B(1)
  ELSE
    factor_nitrf = -((1.0d0-u_nitrf)/u_nitrf*LOG(1.0d0-u_nitrf))
    CALL PUSHCONTROL2B(2)
