  IF (branch .EQ. 0) THEN
    temp6 = (-u_nh4_tr+1.0d0)/u_nh4_tr
    tempb5 = -(LOG(1.0d0-u_nh4_tr)*factor_nh4_trb/u_nh4_tr)
    u_nh4_trb = temp6*factor_nh4_trb/(1.0d0-u_nh4_tr) - (temp6+1.0)*&
&     tempb5
  ELSE IF (branch .EQ. 1) THEN
    u_nh4_trb = 0.D0
  ELSE
    u_nh4_trb = 0.D0
  END IF
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    y5b = u_nh4_trb
  ELSE
    y5b = 0.D0
  END IF
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    u_nh4_trb = y5b
  ELSE
    u_nh4_trb = 0.D0
  END IF
  tempb5 = dt*u_nh4_trb/(eps+y(inh4))
  growtrnh4b = growtrnh4b + tempb5
  yb(inh4) = yb(inh4) - growtrnh4*tempb5/(eps+y(inh4))
  beta_nf = r_std*(1.0d0-epsilon_nf/1000.0d0)
  tempb5 = growtr15nfb/(beta_nf+1.0d0)
  growtrnfb = growtrnfb + beta_nf*tempb5
  beta_nfb = (growtrnf-growtrnf*beta_nf/(beta_nf+1.0d0))*tempb5
  r_stdb = r_stdb + (1.0d0-epsilon_nf/1000.0d0)*beta_nfb
  epsilon_nfb = epsilon_nfb - r_std*beta_nfb/1000.0d0
  growtrnb = growtrnb + growtrnfb
  growtrnh4b = growtrnh4b - growtrnfb
  growtrno3b = growtrno3b - growtrnfb
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    growtrnh4b = growtrnh4b + growtrnb
    growtrno3b = growtrno3b + growtrnb
    maxtrnfb = growtrnb
    v_trnb = 0.D0
    v_trmax_nb = 0.D0
  ELSE
    yb(itrc) = yb(itrc) + v_trn*v_trmax_n*growtrnb
    v_trnb = v_trmax_n*y(itrc)*growtrnb
    v_trmax_nb = v_trn*y(itrc)*growtrnb
    maxtrnfb = 0.D0
  END IF
  CALL POPCONTROL2B(branch)
  IF (branch .NE. 0) THEN
    IF (branch .EQ. 1) THEN
      y4b = 0.D0
    ELSE
      y4b = maxtrnfb
    END IF
    temp6 = v_trmax_n*tfunc/(c1+q_tr_max_n*zeta_nf)
    tempb4 = temp6*y4b
    tempb5 = (q_tr_max_n*(y(itrc)+growtrc-growtrno3*zeta)-y(itrn)-&
&     growtrno3-growtrnh4)*y4b/(c1+q_tr_max_n*zeta_nf)
    v_trmax_nb = v_trmax_nb + tfunc*tempb5
    tfuncb = tfuncb + v_trmax_n*tempb5
    zeta_nfb = zeta_nfb - q_tr_max_n*temp6*tempb5
    tempb3 = q_tr_max_n*tempb4
    yb(itrn) = yb(itrn) - tempb4
    growtrno3b = growtrno3b - tempb4 - zeta*tempb3
    growtrnh4b = growtrnh4b - tempb4
    yb(itrc) = yb(itrc) + tempb3
    growtrcb = growtrcb + tempb3
    zetab = zetab - growtrno3*tempb3
  END IF
  temp6 = k_no3tr/k_nh4tr
  temp5 = y(ino3) + k_no3tr + y(inh4)*temp6
  temp3 = y(itrc)*y(ino3)
  tempb3 = growtrno3b/temp5
  v_trnb = v_trnb + v_trmax_n*temp3*tempb3
  v_trmax_nb = v_trmax_nb + v_trn*temp3*tempb3
  tempb2 = v_trn*v_trmax_n*tempb3
  tempb4 = -(v_trn*v_trmax_n*temp3*tempb3/temp5)
  yb(ino3) = yb(ino3) + tempb4
  yb(inh4) = yb(inh4) + temp6*tempb4
  tempb5 = y(inh4)*tempb4/k_nh4tr
  k_no3trb = tempb4 + tempb5
  k_nh4trb = -(temp6*tempb5)
  yb(itrc) = yb(itrc) + y(ino3)*tempb2
  yb(ino3) = yb(ino3) + y(itrc)*tempb2
  temp6 = k_nh4tr/k_no3tr
  temp5 = y(inh4) + k_nh4tr + y(ino3)*temp6
  temp3 = y(itrc)*y(inh4)
  tempb3 = growtrnh4b/temp5
  v_trnb = v_trnb + v_trmax_n*temp3*tempb3
  v_trmax_nb = v_trmax_nb + v_trn*temp3*tempb3
  tempb2 = v_trn*v_trmax_n*tempb3
  tempb4 = -(v_trn*v_trmax_n*temp3*tempb3/temp5)
  yb(inh4) = yb(inh4) + tempb4
  yb(ino3) = yb(ino3) + temp6*tempb4
  tempb5 = y(ino3)*tempb4/k_no3tr
  k_nh4trb = k_nh4trb + tempb4 + tempb5
  k_no3trb = k_no3trb - temp6*tempb5
  yb(itrc) = yb(itrc) + y(inh4)*tempb2
  yb(inh4) = yb(inh4) + y(itrc)*tempb2
  CALL POPCONTROL1B(branch)
  IF (branch .NE. 0) v_trmax_nb = 0.D0
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    tempb5 = -(v_trmax_nb/(y(itrc)*(q_tr_max_n-q_tr_rdf_n)))
    yb(itrn) = yb(itrn) + tempb5
    yb(itrc) = yb(itrc) - y(itrn)*tempb5/y(itrc)
  END IF
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    pc_trmaxb = 0.D0
  ELSE
    temp6 = EXP(-(a_tr*rlt))
    temp5 = y(itrchl)*alpha_tr*rlt/(y(itrc)*pc_trmax)
    tempb4 = EXP(-temp5)*temp6*growtrcb
    tempb2 = (c1-EXP(-temp5))*growtrcb
    yb(itrc) = yb(itrc) + pc_trmax*temp6*tempb2
    tempb1 = EXP(-(a_tr*rlt))*y(itrc)*pc_trmax*tempb2
    a_trb = a_trb - rlt*tempb1
    rltb = rltb + alpha_tr*y(itrchl)*tempb4 - a_tr*tempb1
    yb(itrchl) = yb(itrchl) + alpha_tr*rlt*tempb4
    alpha_trb = alpha_trb + rlt*y(itrchl)*tempb4
    tempb3 = -(temp5*tempb4)
    pc_trmaxb = y(itrc)*temp6*tempb2 + y(itrc)*tempb3
    yb(itrc) = yb(itrc) + pc_trmax*tempb3
  END IF
  mu_trb = temp*pc_trmaxb
  tempb = mu_tr*pc_trmaxb
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) tempb = 0.D0
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) tempb = 0.D0
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    CALL POPREAL8(temp)
    nfunc_tr_pb = tempb
  ELSE
    CALL POPREAL8(temp)
    nfunc_tr_nb = nfunc_tr_nb + tempb
    nfunc_tr_pb = 0.D0
  END IF
  tempb5 = nfunc_tr_pb/(y(itrc)*(q_tr_rdf_p-q_tr_min_p))
  yb(itrp) = yb(itrp) + tempb5
  yb(itrc) = yb(itrc) - y(itrp)*tempb5/y(itrc)
  tempb5 = nfunc_tr_nb/(y(itrc)*(q_tr_rdf_n-q_tr_min_n))
  yb(itrn) = yb(itrn) + tempb5
  yb(itrc) = yb(itrc) - y(itrn)*tempb5/y(itrc)
  tempb5 = dydttb(ispchl)/secperday
  dydttb(ispchl) = 0.D0
  growspchlb = tempb5
  grazspchlb = -tempb5
  pomspchlb = -tempb5
  tempb5 = dydttb(ispp)/secperday
  dydttb(ispp) = 0.D0
  growsppb = growsppb + tempb5
  excrsp_1pb = excrsp_1pb - tempb5
  excrsp_2pb = excrsp_2pb - tempb5
  grazsppb = grazsppb - tempb5
  pomsppb = pomsppb - tempb5
  tempb5 = dydttb(isp15n)/secperday
  dydttb(isp15n) = 0.D0
  growsp15nb = growsp15nb + tempb5
  excrsp_1_15nb = excrsp_1_15nb - tempb5
  excrsp_2_15nb = excrsp_2_15nb - tempb5
  grazsp15nb = grazsp15nb - tempb5
  pomsp15nb = pomsp15nb - tempb5
  tempb5 = dydttb(ispn)/secperday
  dydttb(ispn) = 0.D0
  growspnb = growspnb + tempb5
  excrsp_1nb = excrsp_1nb - tempb5
  excrsp_2nb = excrsp_2nb - tempb5
  grazspnb = grazspnb - tempb5
  pomspnb = pomspnb - tempb5
  tempb5 = dydttb(ispc)/secperday
  dydttb(ispc) = 0.D0
  growspcb = growspcb + tempb5
  excrsp_1cb = excrsp_1cb - tempb5
  excrsp_2cb = excrsp_2cb - tempb5
  grazspcb = grazspcb - tempb5
  pomspcb = pomspcb - tempb5
  respspb = respspb - tempb5
  tempb5 = grazspchlb/y(ispn)
  grazspnb = grazspnb + y(ispchl)*tempb5
  yb(ispchl) = yb(ispchl) + grazspn*tempb5
  yb(ispn) = yb(ispn) - grazspn*y(ispchl)*tempb5/y(ispn)
  tempb5 = grazsppb/y(ispc)
  grazspcb = grazspcb + y(ispp)*tempb5
  yb(ispp) = yb(ispp) + grazspc*tempb5
  yb(ispc) = yb(ispc) - grazspc*y(ispp)*tempb5/y(ispc)
  tempb5 = grazsp15nb/(beta_sp_graz+1.0d0)
  grazspnb = grazspnb + beta_sp_graz*tempb5
  beta_sp_grazb = (grazspn-grazspn*beta_sp_graz/(beta_sp_graz+1.0d0))*&
&   tempb5
  rspb = (1.0d0-epsilon_g/1000.0d0*factor_sp_graz)*beta_sp_grazb
  epsilon_gb = epsilon_gb - factor_sp_graz*rsp*beta_sp_grazb/1000.0d0
  factor_sp_grazb = -(epsilon_g*rsp*beta_sp_grazb/1000.0d0)
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    temp6 = (-u_sp_graz+1.0d0)/u_sp_graz
    tempb5 = -(LOG(1.0d0-u_sp_graz)*factor_sp_grazb/u_sp_graz)
    u_sp_grazb = temp6*factor_sp_grazb/(1.0d0-u_sp_graz) - (temp6+1.0)*&
&     tempb5
  ELSE
    u_sp_grazb = 0.D0
  END IF
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    y3b = u_sp_grazb
  ELSE
    y3b = 0.D0
  END IF
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    u_sp_grazb = y3b
  ELSE
    u_sp_grazb = 0.D0
  END IF
  tempb5 = dt*u_sp_grazb/(eps+y(ispn))
  grazspnb = grazspnb + tempb5
  yb(ispn) = yb(ispn) - grazspn*tempb5/(eps+y(ispn))
  tempb5 = grazspnb/y(ispc)
  grazspcb = grazspcb + y(ispn)*tempb5
  yb(ispn) = yb(ispn) + grazspc*tempb5
  yb(ispc) = yb(ispc) - grazspc*y(ispn)*tempb5/y(ispc)
  temp6 = g_sp*g_sp/(g_ba*g_ba)
  temp5 = g_sp*g_sp/(g_un*g_un)
  temp4 = y(ispc)*y(ispc) + g_sp*g_sp + y(iunc)*y(iunc)*temp5 + y(ibac)*&
&   y(ibac)*temp6
  temp2 = y(ispc)*y(ispc)
  tempb2 = grazspcb/temp4
  mu_prtb = mu_prtb + y(iprtc)*temp2*tempb2
  yb(iprtc) = yb(iprtc) + mu_prt*temp2*tempb2
  tempb3 = -(mu_prt*y(iprtc)*temp2*tempb2/temp4)
  yb(ispc) = yb(ispc) + 2*y(ispc)*mu_prt*y(iprtc)*tempb2 + 2*y(ispc)*&
&   tempb3
  yb(iunc) = yb(iunc) + 2*y(iunc)*temp5*tempb3
  tempb4 = y(iunc)**2*tempb3/g_un**2
  yb(ibac) = yb(ibac) + 2*y(ibac)*temp6*tempb3
  tempb5 = y(ibac)**2*tempb3/g_ba**2
  g_spb = g_spb + 2*g_sp*tempb3 + 2*g_sp*tempb5 + 2*g_sp*tempb4
  g_bab = g_bab - 2*g_ba*temp6*tempb5
  g_unb = g_unb - 2*g_un*temp5*tempb4
  tempb5 = pomspchlb/y(ispn)
  pomspnb = pomspnb + y(ispchl)*tempb5
  yb(ispchl) = yb(ispchl) + pomspn*tempb5
  yb(ispn) = yb(ispn) - pomspn*y(ispchl)*tempb5/y(ispn)
  tempb5 = pomsppb/y(ispc)
  pomspcb = pomspcb + y(ispp)*tempb5
  yb(ispp) = yb(ispp) + pomspc*tempb5
  yb(ispc) = yb(ispc) - pomspc*y(ispp)*tempb5/y(ispc)
  tempb5 = pomsp15nb/(rsp+1.0d0)
  pomspnb = pomspnb + rsp*tempb5
  rspb = rspb + (pomspn-pomspn*rsp/(rsp+1.0d0))*tempb5
  tempb5 = pomspnb/y(ispc)
  pomspcb = pomspcb + y(ispn)*tempb5
  yb(ispn) = yb(ispn) + pomspc*tempb5
  yb(ispc) = yb(ispc) + 2*y(ispc)*r_pomsp*pomspcb - pomspc*y(ispn)*&
&   tempb5/y(ispc)
  r_pomspb = y(ispc)**2*pomspcb
  tempb5 = excrsp_2_15nb/(rsp+1.0d0)
  excrsp_2nb = excrsp_2nb + rsp*tempb5
  rspb = rspb + (excrsp_2n-excrsp_2n*rsp/(rsp+1.0d0))*tempb5
  r_excrsp_2b = growspc*0.25*excrsp_2cb
  growspcb = growspcb + r_excrsp_2*0.25*excrsp_2cb
  CALL POPCONTROL1B(branch)
  IF (branch .NE. 0) THEN
    min2b = 0.5*excrsp_2pb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      excrsp_2cb = excrsp_2cb + q_sp_rdf_p*min2b
      temp1b = 0.D0
    ELSE
      yb(ispp) = yb(ispp) + temp1*0.25d0*min2b
      temp1b = y(ispp)*0.25d0*min2b
    END IF
    min1b = 0.5*excrsp_2nb
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      excrsp_2cb = excrsp_2cb + q_sp_rdf_n*min1b
      tempb = 0.D0
    ELSE
      yb(ispn) = yb(ispn) + temp*0.25d0*min1b
      tempb = y(ispn)*0.25d0*min1b
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      tempb5 = -(q_sp_rdf_p*temp1b/(q_sp_rdf_n*y(ispp)))
      yb(ispn) = yb(ispn) + tempb5
      yb(ispp) = yb(ispp) - y(ispn)*tempb5/y(ispp)
    END IF
    CALL POPCONTROL1B(branch)
    IF (branch .EQ. 0) THEN
      tempb5 = -(q_sp_rdf_n*tempb/(q_sp_rdf_p*y(ispn)))
      yb(ispp) = yb(ispp) + tempb5
      yb(ispn) = yb(ispn) - y(ispp)*tempb5/y(ispn)
    END IF
  END IF
  yb(ispc) = yb(ispc) + max1*0.5*excrsp_2cb
  max1b = y(ispc)*0.5*excrsp_2cb
  CALL POPCONTROL1B(branch)
  IF (branch .EQ. 0) THEN
    tempb = 0.D0
  ELSE
    tempb = max1b
  END IF
